import sys,re,json
from aiohttp import web
import core
NODE=int(sys.argv[sys.argv.index('--node')+1]) if '--node' in sys.argv else 0
def json_error(status,msg): return web.json_response({'error':msg},status=status)
async def read_json(req):
    try:
        x=await req.json(); return x if isinstance(x,dict) else None
    except: return None
def require_user(req):
    h=req.headers.get('Authorization','')
    if not h.startswith('Bearer '): raise web.HTTPUnauthorized()
    u=core.user_for_token(h[7:])
    if not u: raise web.HTTPUnauthorized()
    return u
async def health(req): return web.json_response({'status':'ok','node_id':NODE})
async def register(req):
    d=await read_json(req)
    if not d or not isinstance(d.get('username'),str) or not re.fullmatch(r'[A-Za-z0-9_]+',d['username']) or not isinstance(d.get('password'),str) or len(d['password'])<8 or 'email' in d:return json_error(400,'invalid registration')
    with core.tx() as c:
        if c.execute('SELECT 1 FROM users WHERE username=?',(d['username'],)).fetchone(): return json_error(409,'username already exists')
        name=d.get('display_name',d['username'])
        if not isinstance(name,str): return json_error(400,'invalid display_name')
        c.execute('INSERT INTO users(username,password,display_name) VALUES(?,?,?)',(d['username'],core.hash_password(d['password']),name))
        u=c.execute('SELECT * FROM users WHERE id=?',(c.lastrowid,)).fetchone(); t=core.issue_token(c,u['id'])
    return web.json_response({'user':core.user_to_json(u),'token':t},status=201)
async def login(req):
    d=await read_json(req)
    if not d or not isinstance(d.get('username'),str) or not isinstance(d.get('password'),str): return json_error(401,'invalid credentials')
    c=core.connect(); u=c.execute('SELECT * FROM users WHERE username=?',(d['username'],)).fetchone()
    if not u or not core.verify_password(d['password'],u['password']): c.close(); return json_error(401,'invalid credentials')
    t=core.issue_token(c,u['id']); c.close(); return web.json_response({'user':core.user_to_json(u),'token':t})
async def me(req):
    try:u=require_user(req)
    except web.HTTPUnauthorized:return json_error(401,'unauthorized')
    return web.json_response({'user':core.user_to_json(u)})
async def ws(req):
    try: require_user(req)
    except web.HTTPUnauthorized:return json_error(401,'unauthorized')
    return web.Response(status=501)
app=web.Application()
app.router.add_get('/api/health',health); app.router.add_post('/api/auth/register',register); app.router.add_post('/api/auth/login',login); app.router.add_get('/api/auth/me',me); app.router.add_get('/api/ws',ws)
if __name__=='__main__': web.run_app(app,host='127.0.0.1',port=8000+NODE)
PY
cat > /app/start.sh <<'SH'
#!/bin/bash
cd /app
mkdir -p /app/data/files
python3 /app/core.py --init-db
(while true; do redis-server --port 6379 --bind 127.0.0.1 --save '' --appendonly no; sleep 1; done) &
for n in 0 1 2; do (while true; do python3 /app/server.py --node $n; sleep 1; done) & done
wait
SH
chmod +x /app/start.sh
python3 -m py_compile /app/core.py /app/server.py && ls -l /app/start.sh /app/requirements.txt /app/core.py /app/server.py
```

