import asyncio, re
import core

NICKS=set()
LOCK=asyncio.Lock()

def sendline(writer, text):
    writer.write((text+'\r\n').encode())

async def handle(reader, writer):
    token=None; nick=None; user=None; registered=False; joined=[]
    try:
        while True:
            raw=await reader.readline()
            if not raw: break
            line=raw.decode(errors='ignore').rstrip('\r\n')
            if not line: continue
            parts=line.split(' ',1); cmd=parts[0].upper(); rest=parts[1] if len(parts)>1 else ''
            args=rest.split(' ') if rest else []
            if cmd=='PASS':
                token=rest.strip()
            elif cmd=='NICK':
                newnick=rest.strip().lstrip(':')
                async with LOCK:
                    if newnick in NICKS and newnick != nick:
                        sendline(writer,f':huddle 433 * {newnick} :Nickname is already in use')
                        await writer.drain(); continue
                    if nick: NICKS.discard(nick)
                    nick=newnick; NICKS.add(nick)
            elif cmd=='USER':
                user=(args[0] if args else 'irc')
            elif cmd=='QUIT':
                break
            elif cmd=='PING':
                val=rest[1:] if rest.startswith(':') else rest
                sendline(writer,f':huddle PONG huddle :{val}')
            elif cmd in ('PONG','NAMES','WHO','LIST','TOPIC','MODE'):
                pass
            elif cmd=='JOIN':
                if not registered:
                    continue
                name=rest.strip().split(' ')[0]
                if not name.startswith('#') or '/' not in name:
                    sendline(writer,f':huddle 403 {nick} {name} :No such channel'); await writer.drain(); continue
                target=name[1:]; slug,cname=target.split('/',1)
                w=core.get_workspace(slug); ch=None
                if w:
                    c=core.connect(); ch=c.execute('SELECT * FROM channels WHERE workspace_id=? AND name=?',(w['id'],cname)).fetchone(); c.close()
                if not ch:
                    sendline(writer,f':huddle 403 {nick} {name} :No such channel'); await writer.drain(); continue
                try: core.join_channel(core.user_for_token(token),ch['id'])
                except: 
                    sendline(writer,f':huddle 403 {nick} {name} :No such channel'); await writer.drain(); continue
                joined.append(name)
                c=core.connect(); ns=c.execute('SELECT u.username FROM users u JOIN channel_members m ON m.user_id=u.id WHERE m.channel_id=? ORDER BY u.username',(ch['id'],)).fetchall(); c.close()
                names=' '.join(x['username'] for x in ns)
                sendline(writer,f':{nick}!{user}@huddle JOIN {name}')
                sendline(writer,f':huddle 353 {nick} = {name} :{names}')
                sendline(writer,f':huddle 366 {nick} {name} :End of /NAMES list')
            elif cmd in ('CAP','USER'):
                pass
            else:
                if nick:
                    sendline(writer,f':huddle 421 {nick} {cmd} :Unknown command')
            if not registered and nick and user is not None:
                u=core.user_for_token(token)
                if not u:
                    sendline(writer,f':huddle 464 * :Password incorrect'); await writer.drain(); break
                registered=True
                for code,text in [('001','Welcome to huddle'),('002','Your host is huddle'),('003','This server was created today'),('004','huddle'),('005','CHANTYPES=#'),('422','MOTD File is missing')]:
                    sendline(writer,f':huddle {code} {nick} :{text}')
            await writer.drain()
    finally:
        if nick:
            async with LOCK: NICKS.discard(nick)
        writer.close()
        try: await writer.wait_closed()
        except: pass

async def main():
    server=await asyncio.start_server(handle,'0.0.0.0',6667)
    async with server: await server.serve_forever()

if __name__=='__main__':
    asyncio.run(main())
